 context=browser.new_context(java_script_enabled=False,viewport={'width':390,'height':844});page=context.new_page();page.goto(base+'/',wait_until='domcontentloaded');check('no-JS both compiled summaries',page.locator('#forecast-static').is_visible() and page.locator('#monitoring-static').is_visible());check('no-JS release text parity',data['summary'] in page.locator('#forecast-static').inner_text());page.locator('#monitoring-static summary').click();check('no-JS finance gaps retained','Land, water and action rights' in page.locator('#monitoring-static').inner_text());check('no-JS forecast download',page.locator('#forecast-static a[download]').get_attribute('href')=='data/forecast-round2.json');context.close();browser.close()
